3	/**
4	 * Telephone-number normalization shared by the owner pipeline: a telephone is
5	 * stored and compared as digits only, so formatting (spaces, dashes and
6	 * parentheses) is insignificant and {@code "(613) 555-0100"} and
7	 * {@code "6135550100"} are treated as the same number.
8	 */
9	final class OwnerTelephones {
10	
11	    private OwnerTelephones() {
12	    }
13	
14	    /**
15	     * Strips every non-digit character, leaving digits only. {@code null} maps to
16	     * {@code null}.
17	     */
18	    static String digitsOnly(String telephone) {
19	        if (telephone == null) {
20	            return null;
21	        }
22	        return telephone.replaceAll("\\D", "");
23	    }
24	}
