1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Objects;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.escalation.OwnerConflictException;
9	import org.springframework.util.StringUtils;
10	
11	/**
12	 * Rejects creating an owner that clashes with an existing one - with a 409 via
13	 * {@link OwnerConflictException}. An owner clashes when its telephone number is
14	 * already used by another owner, or (when an email address is provided) when that
15	 * email is already used by another owner.
16	 *
17	 * <p>Email duplicate detection is insensitive to letter case and to surrounding or
18	 * repeated whitespace: values are {@link #normalize(String) normalized} before
19	 * comparison, so {@code "  john   smith "} and {@code "John Smith"} are treated as
20	 * the same value. Telephone duplicate detection compares
21	 * {@link OwnerTelephones#digitsOnly(String) digits only}, so {@code "(613) 555-0100"}
22	 * and {@code "6135550100"} are treated as the same number.
23	 */
24	public class EnsureOwnerUnique {
25	
26	    public void service(@Val Owner owner, OwnerRepository ownerRepository) throws OwnerConflictException {
27	        String telephone = OwnerTelephones.digitsOnly(owner.getTelephone());
28	        String email = normalize(owner.getEmail());
29	        boolean hasEmail = StringUtils.hasText(email);
30	        for (Owner existing : ownerRepository.findAll()) {
31	            if (Objects.equals(OwnerTelephones.digitsOnly(existing.getTelephone()), telephone)) {
32	                throw new OwnerConflictException(
33	                        "An owner with the same telephone already exists");
34	            }
35	            if (hasEmail && Objects.equals(normalize(existing.getEmail()), email)) {
36	                throw new OwnerConflictException(
37	                        "An owner with the same email already exists");
38	            }
39	        }
40	    }
41	
42	    /**
43	     * Normalizes a value for case- and whitespace-insensitive comparison: trims
44	     * surrounding whitespace, collapses each run of internal whitespace to a single
45	     * space, and lower-cases the result. {@code null} maps to {@code null}.
46	     */
47	    private static String normalize(String value) {
48	        if (value == null) {
49	            return null;
50	        }
51	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
52	    }
53	}
