11	/**
12	 * Rejects creating an owner once the maximum number of owners for a single day has
13	 * already been reached - with a 400 via {@link OwnerDailyLimitException}. The day is
14	 * the owner's registration date, and the count is the number of existing owners
15	 * sharing that same registration date. As {@link BuildOwner} defaults a missing
16	 * registration date to today, a normal create is limited to at most
17	 * {@value #MAX_OWNERS_PER_DAY} owners registered today.
18	 */
19	public class EnforceOwnerDailyLimit {
20	
21	    static final int MAX_OWNERS_PER_DAY = 20;
22	
23	    public void service(@Val Owner owner, OwnerRepository ownerRepository) throws OwnerDailyLimitException {
24	        LocalDate registrationDate = owner.getRegistrationDate();
25	        long registeredThatDay = ownerRepository.findAll().stream()
26	                .filter(existing -> Objects.equals(existing.getRegistrationDate(), registrationDate))
27	                .count();
28	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
29	            throw new OwnerDailyLimitException(
30	                    "The maximum of " + MAX_OWNERS_PER_DAY + " owners for a single day has already been reached");
31	        }
32	    }
33	}
