9	/**
10	 * Rejects creating an owner once the owner's city already contains the maximum number
11	 * of owners - with a 400 via {@link OwnerCityLimitException}. The count is the number
12	 * of existing owners whose city matches the new owner's city, compared
13	 * case-insensitively (consistent with {@link NormalizeOwnerCity}). An owner with a
14	 * blank city is not subject to the cap.
15	 */
16	public class EnforceOwnerCityLimit {
17	
18	    static final int MAX_OWNERS_PER_CITY = 8;
19	
20	    public void service(@Val Owner owner, OwnerRepository ownerRepository) throws OwnerCityLimitException {
21	        String city = owner.getCity();
22	        if (!StringUtils.hasText(city)) {
23	            return;
24	        }
25	        long inCity = ownerRepository.findAll().stream()
26	                .map(Owner::getCity)
27	                .filter(existingCity -> existingCity != null && existingCity.equalsIgnoreCase(city))
28	                .count();
29	        if (inCity >= MAX_OWNERS_PER_CITY) {
30	            throw new OwnerCityLimitException(
31	                    "The maximum of " + MAX_OWNERS_PER_CITY + " owners for a single city has already been reached");
32	        }
33	    }
