1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.util.StringUtils;
7	
8	/**
9	 * Normalizes a newly created owner's city name. The city is title-cased (each
10	 * whitespace-separated word gets a leading capital and a lower-cased remainder,
11	 * e.g. {@code "new york"} becomes {@code "New York"}). However, if an owner already
12	 * exists in that city - matched case-insensitively - the existing owner's exact
13	 * spelling of the city name is reused instead, so a city is spelled consistently
14	 * across all owners regardless of how later creators capitalize it.
15	 */
16	public class NormalizeOwnerCity {
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
19	        String city = owner.getCity();
20	        if (!StringUtils.hasText(city)) {
21	            return;
22	        }
23	        for (Owner existing : ownerRepository.findAll()) {
24	            String existingCity = existing.getCity();
25	            if (existingCity != null && existingCity.equalsIgnoreCase(city)) {
26	                owner.setCity(existingCity);
27	                return;
28	            }
29	        }
30	        owner.setCity(titleCase(city));
31	    }
32	
33	    /**
34	     * Title-cases each whitespace-separated word: leading character upper-cased,
35	     * the remainder lower-cased. Preserves the original whitespace between words.
36	     */
37	    private static String titleCase(String value) {
38	        StringBuilder result = new StringBuilder(value.length());
39	        boolean startOfWord = true;
40	        for (int i = 0; i < value.length(); i++) {
41	            char c = value.charAt(i);
42	            if (Character.isWhitespace(c)) {
43	                startOfWord = true;
44	                result.append(c);
45	            }
46	            else if (startOfWord) {
47	                result.append(Character.toUpperCase(c));
48	                startOfWord = false;
49	            }
50	            else {
51	                result.append(Character.toLowerCase(c));
52	            }
53	        }
54	        return result.toString();
55	    }
56	}
