12	public class AssignOwnerCustomerCode {
13	
14	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
15	        String city = owner.getCity();
16	        long inCity = ownerRepository.findAll().stream()
17	                .filter(existing -> city == null ? existing.getCity() == null
18	                        : city.equals(existing.getCity()))
19	                .count();
20	        String code = String.format("%s-%04d", city == null ? "" : city.toUpperCase(), inCity + 1);
21	        owner.setCustomerCode(code);
22	    }
23	}
